if ((q_bi == NULL) || (inertial == NULL) || (body == NULL) || (trace == NULL) ||
    (symmetry_error == NULL)) {
    if (body != NULL) {
        for (i = 0; i < 3; i++)
            for (j = 0; j < 3; j++)
                body->m[i][j] = 0.0;
    }
    if (trace != NULL)
        *trace = 0.0;
    if (symmetry_error != NULL)
        *symmetry_error = INFINITY;
    return ADCS_E_NULL;
}

int ok = 1;
for (i = 0; i < 3; i++) {
    for (j = 0; j < 3; j++) {
        if (!isfinite(inertial->m[i][j]))
            ok = 0;
    }
}
if ((inertial->m[0][0] < 0.0) || (inertial->m[1][1] < 0.0) || (inertial->m[2][2] < 0.0))
    ok = 0;
if (!isfinite(q_bi->w) || !isfinite(q_bi->x) || !isfinite(q_bi->y) || !isfinite(q_bi->z))
    ok = 0;

if (ok == 0) {
    for (i = 0; i < 3; i++)
        for (j = 0; j < 3; j++)
            body->m[i][j] = 0.0;
    *trace = 0.0;
    *symmetry_error = INFINITY;
    return ADCS_E_RANGE;
}

if (adcs_quat_normalize(q_bi, &qn) != ADCS_OK) {
    for (i = 0; i < 3; i++)
        for (j = 0; j < 3; j++)
            body->m[i][j] = 0.0;
    *trace = 0.0;
    *symmetry_error = INFINITY;
    return ADCS_E_RANGE;
}

c_bi = adcs_quat_to_dcm_bi(&qn);
c_bi_t = adcs_mat3_transpose(&c_bi);
p_b = adcs_mat3_mul(&c_bi, inertial);
p_b = adcs_mat3_mul(&p_b, &c_bi_t);

*body = p_b;

tr = p_b.m[0][0] + p_b.m[1][1] + p_b.m[2][2];
*trace = tr;

sym = fabs(p_b.m[0][1] - p_b.m[1][0]) + fabs(p_b.m[0][2] - p_b.m[2][0]) +
      fabs(p_b.m[1][2] - p_b.m[2][1]);
*symmetry_error = sym;

return ADCS_OK;
